public class ContactTriggerHandler {
    /**
     * Handles before insert and before update logic.
     *  - Copies Account.BillingCountry to Contact.MailingCountry when blank.
     *  - Copies Account.AccountSource to Contact.LeadSource on insert when blank.
     */
    public static void handleBefore(
        Boolean isInsert,
        Boolean isUpdate,
        List<Contact> newContacts,
        Map<Id, Contact> oldMap
    ) {
        // Collect Account IDs needed for field retrieval
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // Query Accounts once (if needed)
        Map<Id, Account> accountMap = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accountMap = new Map<Id, Account>(
                [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
            );
        }

        // Apply logic to each contact
        for (Contact c : newContacts) {
            Account acc = accountMap.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = acc.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = acc.AccountSource;
            }
        }
    }

    /**
     * Handles after insert logic:
     *  - For each inserted Contact with a phone, if its Account's phone is blank,
     *    set the account phone to the contact's phone.
     *    Only the first contact (in trigger order) per account will set the phone.
     */
    public static void handleAfterInsert(List<Contact> newContacts) {
        // Determine which accounts we need to inspect (those with a contact phone)
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        // Query Accounts for their current phone numbers
        Map<Id, Account> accountMap = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accountMap = new Map<Id, Account>(
                [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        Set<Id> accountsWithPhoneSet = new Set<Id>(); // tracks accounts we already decided to update

        // Process contacts in trigger order to preserve "first wins" behavior
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account acc = accountMap.get(c.AccountId);
            if (acc == null) {
                continue;
            }
            if (String.isBlank(acc.Phone) && !accountsWithPhoneSet.contains(c.AccountId)) {
                acc.Phone = c.Phone;
                accountsToUpdate.add(acc);
                accountsWithPhoneSet.add(c.AccountId);
            }
        }

        // Perform a single DML update if needed
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
