public class OrderPayloadParser {
    public static Order parse(String body) {
        if (body == null || body.trim() == '') {
            throw new PayloadException('Body is null or blank');
        }
        Object jsonObj;
        try {
            jsonObj = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON');
        }
        if (!(jsonObj instanceof Map<String,Object>)) {
            throw new PayloadException('JSON root is not an object');
        }
        Map<String,Object> m = (Map<String,Object>) jsonObj;

        // orderNumber
        Object numObj = m.get('number');
        if (numObj == null || !(numObj instanceof String) || ((String)numObj).trim() == '') {
            throw new PayloadException('Missing or blank order number');
        }
        String orderNumber = ((String)numObj).trim();

        // orderDate
        Date orderDate = null;
        Object dateObj = m.get('date');
        if (dateObj instanceof String) {
            String dateStr = ((String)dateObj).trim();
            if (!dateStr.equals('')) {
                try {
                    orderDate = Date.valueOf(dateStr);
                } catch (Exception e) {
                    throw new PayloadException('Invalid date format');
                }
            }
        }

        // currencyCode
        String currencyCode = null;
        Object curObj = m.get('currency');
        if (curObj instanceof String) {
            currencyCode = ((String)curObj);
        }

        // customerEmail
        String customerEmail = null;
        Object custObj = m.get('customer');
        if (custObj instanceof Map) {
            Map<String,Object> custMap = (Map<String,Object>)custObj;
            Object emailObj = custMap.get('email');
            if (emailObj instanceof String) {
                customerEmail = ((String)emailObj);
            }
        }

        // lines
        List<Line> lines = new List<Line>();
        Object linesObj = m.get('lines');
        if (linesObj instanceof List) {
            List<Object> rawLines = (List<Object>)linesObj;
            for (Object lineObj : rawLines) {
                if (!(lineObj instanceof Map)) {
                    throw new PayloadException('Line is not an object');
                }
                Map<String,Object> lineMap = (Map<String,Object>)lineObj;

                // sku
                Object skuObj = lineMap.get('sku');
                if (skuObj == null || !(skuObj instanceof String) || ((String)skuObj).trim() == '') {
                    throw new PayloadException('Line missing or blank sku');
                }
                String sku = ((String)skuObj).trim();

                // quantity
                Object qtyObj = lineMap.get('quantity');
                if (qtyObj == null) {
                    throw new PayloadException('Line missing quantity');
                }
                Decimal qtyDec;
                try {
                    qtyDec = (Decimal)qtyObj;
                } catch (Exception e) {
                    throw new PayloadException('Quantity must be numeric');
                }
                if (qtyDec == null || qtyDec <= 0 || qtyDec.round() != qtyDec) {
                    throw new PayloadException('Quantity must be positive integer');
                }
                Integer quantity = qtyDec.intValue();

                // unitPrice
                Object priceObj = lineMap.get('unitPrice');
                if (priceObj == null) {
                    throw new PayloadException('Line missing unitPrice');
                }
                Decimal unitPrice;
                try {
                    unitPrice = (Decimal)priceObj;
                } catch (Exception e) {
                    throw new PayloadException('unitPrice must be numeric');
                }
                if (unitPrice < 0) {
                    throw new PayloadException('unitPrice cannot be negative');
                }

                // discount
                Decimal discount = 0;
                Object discObj = lineMap.get('discount');
                if (discObj != null) {
                    try {
                        discount = (Decimal)discObj;
                    } catch (Exception e) {
                        discount = 0;
                    }
                    if (discount < 0) discount = 0;
                    if (discount > 1) discount = 1;
                }

                // lineTotal
                Decimal lineTotal = quantity * unitPrice * (1 - discount);
                lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);
                lines.add(new Line(sku, quantity, unitPrice, discount, lineTotal));
            }
        }

        // total
        Decimal total = 0;
        for (Line l : lines) {
            total += l.lineTotal;
        }
        total = total.setScale(2, RoundingMode.HALF_UP);

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String,Object> resp = new Map<String,Object>();
        resp.put('number', order.orderNumber);
        resp.put('status', 'RECEIVED');
        resp.put('lineCount', order.lines.size());
        resp.put('total', order.total);
        return JSON.serialize(resp);
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;

        public Line(String sku, Integer quantity, Decimal unitPrice, Decimal discount, Decimal lineTotal) {
            this.sku = sku;
            this.quantity = quantity;
            this.unitPrice = unitPrice;
            this.discount = discount;
            this.lineTotal = lineTotal;
        }
    }

    public class PayloadException extends Exception {
        public PayloadException(String msg) {
            super(msg);
        }
    }
}
