with sharing public class LeadImportService {
    /**
     * Result of the lead import operation.
     */
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    /**
     * Inserts leads from a list, applying business rules:
     * - Sets LeadSource to 'Web' when blank.
     * - Treats leads with the same email (case‑insensitive, trimmed) as duplicates;
     *   only the first is attempted; later duplicates get a duplicate‑email error.
     * - Uses a single DML statement; partial success is allowed.
     * - Returns counts, inserted IDs, and per‑index error messages.
     *
     * @param leads List of Lead tokens to import (may be null or empty).
     * @return ImportResult summarizing the outcome.
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        // Handle null or empty input early.
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Track emails we have already seen (first occurrence wins).
        Map<String, Integer> emailSeen = new Map<String, Integer>();

        // Leads that will actually be sent to the DB.
        List<Lead> toInsert = new List<Lead>();
        // Mapping from position in toInsert back to original index in the input list.
        List<Integer> insertOrigIndex = new List<Integer>();

        // First pass: detect duplicates, set LeadSource, prepare inserts.
        for (Integer i = 0; i < leads.size(); i++) {
            Lead src = leads[i];
            // Work on a clone to avoid altering the caller's list.
            Lead lead = src.clone(false, true, false, false);

            // Ensure LeadSource is 'Web' when blank.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            String email = lead.Email;
            Boolean isDuplicate = false;

            if (email != null) {
                email = email.trim().toLowerCase();
                // Consider only non‑blank emails for duplicate detection.
                if (email != '') {
                    if (emailSeen.containsKey(email)) {
                        isDuplicate = true;
                        result.errorsByIndex.put(i, 'Duplicate email in import: ' + email);
                    } else {
                        emailSeen.put(email, i);
                    }
                }
            }

            if (!isDuplicate) {
                toInsert.add(lead);
                insertOrigIndex.add(i);
            }
        }

        // If there are leads to insert, perform a single DML with partial success allowed.
        if (!toInsert.isEmpty()) {
            Database.SaveResult[] srList = Database.insert(toInsert, false);
            for (Integer j = 0; j < srList.size(); j++) {
                Integer originalIndex = insertOrigIndex.get(j);
                Database.SaveResult sr = srList[j];
                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    StringBuilder errMsg = new StringBuilder();
                    for (Database.Error e : sr.getErrors()) {
                        if (errMsg.length() > 0) errMsg.append('; ');
                        errMsg.append(e.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, errMsg.toString());
                }
            }
        }

        return result;
    }
}
