            ev.Order_Number__c = s.orderNumber;
            ev.Tracking_Number__c = s.trackingNumber;
            ev.Carrier__c = s.carrier;
            eventsToPublish.add(ev);
        }

        if (eventsToPublish.isEmpty()) {
            return 0;
        }

        List<EventBus.PublishStatus> publishStatusList = EventBus.publish(eventsToPublish);
        Integer successCount = 0;
        for (EventBus.PublishStatus status : publishStatusList) {
            if (status.isSuccess()) {
                successCount++;
            }
        }
        return successCount;
    }
