public class LogPurgeJob implements Schedulable {
    public LogPurgeJob() {
        // No‑argument constructor required by Schedulable interface
    }

    public void execute(SchedulableContext sc) {
        // Calculate cutoff dates
        DateTime thirtyDaysAgo   = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        // Query logs to delete:
        // - Non‑ERROR logs older than 30 days
        // - ERROR logs older than 180 days
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
               OR (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
        ];

        if (!logsToDelete.isEmpty()) {
            // Use partial=false to fail the whole batch on any error (adjust as needed)
            Database.delete(logsToDelete, false);
        }
    }

    /**
     * Schedules the job to run nightly at 02:00.
     * @return Id of the scheduled job
     */
    public static Id scheduleNightly() {
        // Cron expression: seconds minutes hours day month day_of_week
        // 0 0 2 * * ?  => at 02:00:00 every day
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
