public with sharing class Opportunities extends fflib_SObjectDomain {
    public static fflib_ISObjectDomain Instance = new Opportunities();

    public Opportunities() {
        super(new List<SObject>());
    }

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public override void onAfterInsert() {
        Set<Id> wonOppIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) records) {
            if (opp.StageName == 'Closed Won') {
                wonOppIds.add(opp.Id);
            }
        }
        if (!wonOppIds.isEmpty()) {
            fulfil(wonOppIds);
        }
    }

    public override void onAfterUpdate(Map<Id, SObject> oldMap, List<SObject> updated) {
        Set<Id> wonOppIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) updated) {
            Opportunity oldOpp = (Opportunity) oldMap.get(opp.Id);
            if (oldOpp.StageName != 'Closed Won' && opp.StageName == 'Closed Won') {
                wonOppIds.add(opp.Id);
            }
        }
        if (!wonOppIds.isEmpty()) {
            fulfil(wonOppIds);
        }
    }

    private void fulfil(Set<Id> oppIds) {
        IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(oppIds);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }
}
