public class ContactPhoneCleanup {
    /**
     * Normalizes the Phone field for the given contact IDs.
     *
     * For each contact with a non‑null Phone, strips every character that is not a digit
     * or a plus sign (+). The cleaned contacts are then updated in a single DML call
     * with allOrNone = false so that validation failures do not block the rest.
     *
     * @param contactIds List of Contact IDs to process (max 200 as per governor limits).
     * @return A map where the key is the Contact ID that failed to save and the value is
     *         the first error message. Returns an empty map when all contacts saved successfully.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        // Query the contacts we need to work on.
        List<Contact> contacts = [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds];
        List<Contact> toUpdate = new List<Contact>();

        for (Contact c : contacts) {
            if (c.Phone == null) {
                // Skip contacts without a phone number.
                continue;
            }
            // Remove every character that is not a digit or '+'.
            String cleaned = c.Phone.replaceAll('[^0-9+]', '');
            c.Phone = cleaned;
            toUpdate.add(c);
        }

        Map<Id, String> errors = new Map<Id, String>();
        if (!toUpdate.isEmpty()) {
            Database.SaveResult[] srList = Database.update(toUpdate, false);
            for (Database.SaveResult sr : srList) {
                if (!sr.isSuccess() && sr.getErrors().size() > 0) {
                    errors.put(sr.getId(), sr.getErrors()[0].getMessage());
                }
            }
        }
        return errors;
    }
}
