/**
 * Queueable class responsible for sending newly created Accounts to the ERP
 * as individual customer records. Each Account results in its own HTTP POST
 * to the ERP API endpoint via the Named Credential "ERP".
 *
 * The Queueable processes Accounts in batches of 100 to stay within the
 * 100 callout limit per transaction, chaining additional batches if needed.
 */
public class ErpCustomerSyncQueueable implements Queueable, Database.AllowsCallouts {
    private Set<Id> accountIds;

    public ErpCustomerSyncQueueable(Set<Id> ids) {
        this.accountIds = ids;
    }

    public void execute(QueueableContext context) {
        // Fetch the Accounts we need to send.
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ];

        // Process in batches of 100 to avoid exceeding the callout limit.
        final Integer BATCH_SIZE = 100;
        for (Integer start = 0; start < accounts.size(); start += BATCH_SIZE) {
            List<Account> batch = accounts.subList(
                start,
                Math.min(start + BATCH_SIZE, accounts.size())
            );

            for (Account acc : batch) {
                // Build JSON payload: [{ salesforceId: "...", name: "...", country: "..." }]
                JSONGenerator gen = JSON.createGenerator(true);
                gen.writeStartArray();
                gen.writeStartObject();
                gen.writeStringField('salesforceId', acc.Id);
                gen.writeStringField('name', acc.Name);
                if (acc.BillingCountry == null) {
                    gen.writeNullField('country');
                } else {
                    gen.writeStringField('country', acc.BillingCountry);
                }
                gen.writeEndObject();
                gen.writeEndArray();
                String jsonBody = gen.getString();

                // Prepare the callout using the Named Credential.
                HttpRequest req = new HttpRequest();
                req.setEndpoint('callout:ERP/api/customers');
                req.setMethod('POST');
                req.setHeader('Content-Type', 'application/json');
                req.setBody(jsonBody);

                Http http = new Http();
                try {
                    HttpResponse res = http.send(req);
                    // ERP returns 202 Accepted; we do not need to handle the response
                    // per the ticket scope. Errors are allowed to propagate and will
                    // be captured in Apex job logs.
                } catch (Exception e) {
                    // Log the exception; in a real implementation you might insert
                    // a custom error object or send an alert.
                    System.debug(
                        LoggingLevel.ERROR,
                        'ErpCustomerSyncQueueable: Failed to send Account Id '
                        + acc.Id + ' to ERP. Error: ' + e.getMessage()
                    );
                }
            }
        }

        // No further chaining is needed because each batch respects the
        // callout limit. If the total number of Accounts ever exceeds the
        // asynchronous job limits, consider using Batch Apex or adjusting
        // the batch size accordingly.
    }
}
