    if (!accountIds.isEmpty()) {
        // We batch the IDs into a single future call to stay within governor limits
        // (50 future calls per Apex transaction). This is more efficient than
        // calling the future method once per opportunity.
        AccountRatingService.recalculate(new List<Id>(accountIds));
    }
