public with sharing class AccountRatingService {
    /**
     * Asynchronously recalculates the Rating field on the supplied Accounts
     * based on their open Opportunities.
     *
     * @param accountIds Set of Account Ids to evaluate
     */
    @future
    public static void recalculate(List<Id> accountIds) {
        // Determine, for each account, the maximum Amount of its open Opportunities
        // and whether it has any open Opportunities at all.
        Map<Id, Decimal> maxAmountByAccount = new Map<Id, Decimal>();
        Map<Id, Boolean> hasOpenByAccount   = new Map<Id, Boolean>();

        for (Opportunity opp : [
                SELECT Id, AccountId, Amount
                FROM Opportunity
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
        ]) {
            hasOpenByAccount.put(opp.AccountId, true);
            Decimal amt = opp.Amount != null ? opp.Amount : 0;
            Decimal currentMax = maxAmountByAccount.get(opp.AccountId);
            if (currentMax == null || amt > currentMax) {
                maxAmountByAccount.put(opp.AccountId, amt);
            }
        }

        // Fetch the Accounts we need to update (only the Rating field)
        Map<Id, Account> accounts = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        List<Account> toUpdate = new List<Account>();

        for (Id accId : accountIds) {
            Boolean hasOpen   = hasOpenByAccount.get(accId);
            Decimal maxAmt    = maxAmountByAccount.get(accId);

            String newRating;
            if (!hasOpen) {
                newRating = 'Cold';
            } else if (maxAmt != null && maxAmt >= 100000) {
                newRating = 'Hot';
            } else {
                newRating = 'Warm';
            }

            Account acc = accounts.get(accId);
            if (acc == null) {
                continue; // Safety net – should not happen
            }

            // Only add to the update list if the rating actually changes
            if (acc.Rating != newRating) {
                acc.Rating = newRating;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
