public with sharing class LineItemDiscountHandler {
    /**
     * Handles the before insert trigger for OpportunityLineItem.
     * Sets the Discount to the standard discount for the product when Discount is null.
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        // Gather Product2Ids that need a discount applied
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount == null) {
                productIds.add(oli.Product2Id);
            }
        }

        // Nothing to do if all lines already have a discount
        if (productIds.isEmpty()) {
            return;
        }

        // Bulk fetch Product2 records to obtain their families
        Map<Id, String> productFamilyMap = new Map<Id, String>();
        for (Product2 p : [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]) {
            productFamilyMap.put(p.Id, p.Family);
        }

        // Apply the standard discount where needed
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount == null) {
                String family = productFamilyMap.get(oli.Product2Id);
                if (family != null) {
                    oli.Discount = PricingRules.standardDiscountForFamily(family);
                }
                // If the product is not found, we leave Discount null;
                // the original PricingRules.standardDiscountFor would throw a QueryException,
                // which is appropriate behavior for a missing product.
            }
        }
    }
}
