            surveyTask.Subject = 'CSAT survey: ' + c.CaseNumber;
            surveyTask.ActivityDate = Date.today().addDays(2);
            surveyTask.Status = 'Not Started';

            insert surveyTask;
        } catch (Exception ex) {
            // Log the error; in a real org you might use custom logging or error handling
            System.debug(LoggingLevel.ERROR, 'CaseSurveyJob failed for Case Id ' + caseId + ': ' + ex.getMessage());
            // Optionally, you could throw a custom exception or send an alert here
        }
