import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    results = [];
    error = null;

    // debounce timer
    _debounceTimer = null;
    // request tracking to ignore stale responses
    _requestId = 0;
    _latestRequestId = 0;
    _isConnected = true;

    handleChange(event) {
        const value = event.target.value.trim();
        this.searchTerm = value;

        // clear any pending debounce
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }

        if (value.length < 2) {
            // cancel pending search and clear results
            this.results = [];
            this.error = null;
            return;
        }

        // schedule search after 300ms
        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._requestId += 1;
            const currentId = this._requestId;
            this._latestRequestId = currentId; // mark as latest
            const term = this.searchTerm.trim();

            searchContacts({ searchTerm: term })
                .then((contacts) => {
                    if (this._isConnected && currentId === this._latestRequestId) {
                        this.results = contacts;
                        this.error = null;
                    }
                })
                .catch((err) => {
                    if (this._isConnected && currentId === this._latestRequestId) {
                        this.error = err.body?.message || err.message || 'Unknown error';
                        this.results = [];
                    }
                });
        }, 300);
    }

    disconnectedCallback() {
        this._isConnected = false;
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
    }
}
