    handleMessage(message) {
        // Update selected record id; treat undefined/missing as null
        this.selectedRecordId = message?.recordId ?? null;
    }

    handleClear() {
        // Publish null to clear selection for all listeners (including self)
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
