import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines; // [{ key, productName, quantity }]
    showError = false;

    handleAction(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this._resetAll();
        } else if (action === 'submit') {
            this._submitAll();
        }
    }

    _resetAll() {
        this.template.querySelectorAll('c-line-item-editor').forEach(editor => {
            editor.reset();
        });
        this.showError = false;
    }

    _submitAll() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;
        editors.forEach(editor => {
            if (!editor.validate()) {
                allValid = false;
            }
        });
        if (allValid) {
            this.showError = false;
            const values = Array.from(editors).map(editor => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: values },
                    bubbles: true,
                    composed: true
                })
            );
        } else {
            this.showError = true;
        }
    }
}
