import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track waiting = 0;
    @track longestWaitMinutes = 0;
    @track error = '';
    @track loaded = false;
    isFetching = false;
    intervalId = null;

    connectedCallback() {
        this.fetchStats();
        this.startPolling();
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            this.fetchStats();
            this.startPolling();
        } else {
            this.stopPolling();
        }
    };

    startPolling() {
        if (this.intervalId) return;
        this.intervalId = setInterval(() => this.fetchStats(), 60000);
    }

    stopPolling() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    fetchStats() {
        if (this.isFetching) return;
        if (document.visibilityState !== 'visible') return;
        this.isFetching = true;
        this.error = '';
        getQueueStats()
            .then(result => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.loaded = true;
                this.error = '';
            })
            .catch(error => {
                const msg = error.body ? error.body.message : (error.message || JSON.stringify(error));
                this.error = msg;
                this.loaded = false;
            })
            .finally(() => {
                this.isFetching = false;
            });
    }
}
