/**
 * EmployerService
 * 
 * Sets a contact's current employer affiliation based on a map of Contact Id -> Organization Account Id.
 * Ensures:
 *   - A Current, primary NPSP affiliation exists between the contact and the organization.
 *   - The contact's primary affiliation lookup (npsp__Primary_Affiliation__c) points to that organization.
 *   - Any previous primary employer affiliation becomes Former, non‑primary with EndDate = today.
 *   - No duplicate affiliation is created if the organization is already the primary affiliation.
 *   - The contact remains in their household account (no changes to AccountId).
 * 
 * Bulk‑safe: handles up to 200 contacts with at most 2 SOQL queries and 2 DML statements.
 */
public class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // Guard clause for null or empty input
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Gather the sets of Contact and Organization IDs we need to work with
        Set<Id> contactIds = employerByContactId.keySet();
        Set<Id> orgIds = new Set<Id>(employerByContactId.values());

        // -----------------------------------------------------------------
        // SOQL #1: Retrieve all existing affiliations for the contacts in scope.
        // We fetch enough fields to determine current primary affiliations and
        // to locate any existing affiliation (any status) for a contact‑org pair.
        // -----------------------------------------------------------------
        List<Affiliation> existingAffils = [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c,
                   npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
        ];

        // Maps for quick look‑ups
        Map<Id, Affiliation> contactToCurrentPrimaryAff = new Map<Id, Affiliation>();
        Map<String, Affiliation> contactOrgKeyToAff = new Map<String, Affiliation>();

        for (Affiliation a : existingAffils) {
            // Track current primary affiliation per contact (if any)
            if ('Current' == a.npe5__Status__c && a.npe5__Primary__c) {
                contactToCurrentPrimaryAff.put(a.npe5__Contact__c, a);
            }
            // Build a composite key for contact‑org lookup
            String key = a.npe5__Contact__c + '_' + a.npe5__Organization__c;
            contactOrgKeyToAff.put(key, a);
        }

        // Lists for DML
        List<Affiliation> affiliationsToUpdate = new List<Affiliation>();
        List<Affiliation> affiliationsToInsert = new List<Affiliation>();

        Date today = Date.today();

        // -----------------------------------------------------------------
        // Process each contact‑employer pair from the incoming map
        // -----------------------------------------------------------------
        for (Id contactId : employerByContactId.keySet()) {
            Id newOrgId = employerByContactId.get(contactId);
            if (newOrgId == null) {
                continue; // skip null employer
            }

            Id currentPrimaryOrgId = null;
            Affiliation currentPrimaryAff = contactToCurrentPrimaryAff.get(contactId);
            if (currentPrimaryAff != null) {
                currentPrimaryOrgId = currentPrimaryAff.npe5__Organization__c;
            }

            // If the organization is already the current primary affiliation, nothing to do
            if (currentPrimaryOrgId == newOrgId) {
                continue;
            }

            // -----------------------------------------------------------------
            // Step 1: Demote the existing primary affiliation (if any) to Former
            // -----------------------------------------------------------------
            if (currentPrimaryAff != null) {
                // Create a mutable copy for update
                Affiliation demoteAff = currentPrimaryAff.clone(false, false, false, false);
                demoteAff.npe5__Status__c = 'Former';
                demoteAff.npe5__Primary__c = false;
                demoteAff.npe5__EndDate__c = today;
                affiliationsToUpdate.add(demoteAff);
            }

            // -----------------------------------------------------------------
            // Step 2: Ensure a Current, primary affiliation exists for the new org
            // -----------------------------------------------------------------
            String newAffKey = contactId + '_' + newOrgId;
            Affiliation existingAff = contactOrgKeyToAff.get(newAffKey);

            if (existingAff != null) {
                // Update the existing record to Current/Primary if it isn't already
                if (!('Current' == existingAff.npe5__Status__c && existingAff.npe5__Primary__c)) {
                    Affiliation updAff = existingAff.clone(false, false, false, false);
                    updAff.npe5__Status__c = 'Current';
                    updAff.npe5__Primary__c = true;
                    updAff.npe5__StartDate__c = today;
                    updAff.npe5__EndDate__c = null; // clear any former end date
                    affiliationsToUpdate.add(updAff);
                }
                // If it is already Current/Primary, nothing else needed (handled by early continue above)
            } else {
                // No affiliation exists – insert a new one
                Affiliation newAff = new Affiliation(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = newOrgId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today
                );
                affiliationsToInsert.add(newAff);
            }
        }

        // -----------------------------------------------------------------
        // DML #1: Update affiliations (demote old primary, adjust existing)
        // DML #2: Insert new affiliations where needed
        // -----------------------------------------------------------------
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
        // Note: NPSP automatically updates Contact.npsp__Primary_Affiliation__c
        // when an affiliation is marked primary, so no separate Contact DML is required.
    }
}
