public class GiftImportService {
    /**
     * Simple container for the incoming gift data from the website.
     */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /**
     * Result of importing a single gift.
     */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // matched or created Contact
        public Id opportunityId;    // created Donation (Opportunity)
        public String errorMessage; // failure details when success is false
    }

    /**
     * Imports a list of WebGift records using NPSP's Data Import (BDI) engine.
     * One npsp__DataImport__c record is staged per gift, then processed
     * synchronously in the same transaction. The staged records remain in the
     * org as an audit trail.
     *
     * @param gifts List of incoming gift data; may be null or empty.
     * @return List of ImportResult objects in the same order as the input.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        // Handle null or empty input early.
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Stage Data Import records.
        List<npsp__DataImport__c> importsToInsert = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c   = g.firstName,
                npsp__Contact1_Lastname__c    = g.lastName,
                npsp__Contact1_Personal_Email__c = g.email,
                npsp__Donation_Amount__c      = g.amount,
                npsp__Donation_Date__c        = g.giftDate
                // npsp__Donation_Donor__c is left null; NPSP will populate after matching/contact creation.
            );
            importsToInsert.add(di);
        }

        // Insert the staged records (audit trail). If this fails, treat every gift as a failure.
        try {
            insert importsToInsert;
        } catch (DmlException e) {
            List<ImportResult> results = new List<ImportResult>();
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult ir = new ImportResult();
                ir.success = false;
                ir.errorMessage = 'Failed to stage import record: ' + e.getMessage();
                results.add(ir);
            }
            return results;
        }

        // Process the staged records via NPSP's Data Import Apex API.
        List<npsp__DataImport__c> processedImports;
        try {
            // The NPSP BD import engine exposes this method.
            processedImports = npsp.DataImport.processImports(importsToInsert);
        } catch (Exception e) {
            // If the processing call itself fails, mark all gifts as failed.
            List<ImportResult> results = new List<ImportResult>();
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult ir = new ImportResult();
                ir.success = false;
                ir.errorMessage = 'Import processing failed: ' + e.getMessage();
                results.add(ir);
            }
            return results;
        }

        // Build the result list from the processed Data Import records.
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < processedImports.size(); i++) {
            npsp__DataImport__c di = processedImports[i];
            ImportResult ir = new ImportResult();
            // NPSP sets Status to 'Imported' on success.
            ir.success = (di.npsp__Status__c == 'Imported');
            ir.contactId = di.npsp__Contact1Imported__c;
            ir.opportunityId = di.npsp__DonationImported__c;
            if (!ir.success) {
                // Failure information is populated on failure.
                ir.errorMessage = di.npsp__FailureInformation__c;
            }
            results.add(ir);
        }

        return results;
    }
}
