public class GauAllocationService {
    public class AllocationException extends Exception {}

    /**
     * Replaces all GAU allocations for the given opportunity with allocations based on the supplied percentages.
     * 
     * @param opportunityId   Id of the Opportunity (gift) to allocate.
     * @param percentByGauId  Map where key is the Id of a npsp__General_Accounting_Unit__c and value is the percentage (e.g., 60 for 60%).
     * @return List of newly inserted npsp__Allocation__c records.
     * @throws AllocationException if validation fails.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // ----- Validation -----
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent map is null or empty.');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        Decimal totalPercent = 0;
        for (Decimal p : percentByGauId.values()) {
            if (p == null) {
                throw new AllocationException('Percent value is null.');
            }
            if (p <= 0) {
                throw new AllocationException('Percent must be greater than zero.');
            }
            totalPercent += p;
        }
        if (totalPercent > 100) {
            throw new AllocationException('Total percent exceeds 100%.');
        }

        // Ensure all GAUs exist and are active
        List<npsp__General_Accounting_Unit__c> gauList = [
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ];
        if (gauList.size() != gauIds.size()) {
            throw new AllocationException('One or more GAUs not found.');
        }
        for (npsp__General_Accounting_Unit__c gau : gauList) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException('GAU is inactive: ' + gau.Id);
            }
        }

        // Get the opportunity amount (treat null as 0)
        Opportunity opp = [SELECT Amount FROM Opportunity WHERE Id = :opportunityId];
        if (opp == null) {
            throw new AllocationException('Opportunity not found.');
        }
        Decimal oppAmount = opp.Amount != null ? opp.Amount : 0;

        // ----- Delete existing allocations -----
        List<npsp__Allocation__c> existingAlloc = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        delete existingAlloc;

        // ----- Create new allocations -----
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Map.Entry<Id, Decimal> entry : percentByGauId.entrySet()) {
            Id gauId = entry.getKey();
            Decimal percent = entry.getValue();
            Decimal amount = (oppAmount * percent) / 100;

            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = amount
                // Other fields (Payment, Campaign, Recurring_Donation) can remain null; they are optional.
            );
            toInsert.add(alloc);
        }
        insert toInsert;
        return toInsert;
    }
}
