public class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    /**
     * Installs a monthly installment plan for an open donation (pledge).
     * 
     * @param opportunityId    Id of the Opportunity (pledge)
     * @param numberOfPayments Number of installments to create (must be >=1)
     * @param firstPaymentDate Date of the first installment
     * @return List of newly inserted npe01__OppPayment__c records in schedule order
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // ---- Validation ----------------------------------------------------
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be >=1.');
        }

        Opportunity opp = [SELECT Id, Amount, IsClosed FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        if (opp == null) {
            throw new PaymentPlanException('Opportunity not found.');
        }
        if (opp.IsClosed) {
            throw new PaymentPlanException('Opportunity is closed.');
        }

        // ---- Fetch existing payments ---------------------------------------
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal paidTotal = 0;
        Decimal writtenOffTotal = 0;
        for (npe01__OppPayment__c p : existingPayments) {
            if (p.npe01__Paid__c) {
                paidTotal += p.npe01__Payment_Amount__c;
            }
            if (p.npe01__Written_Off__c) {
                writtenOffTotal += p.npe01__Payment_Amount__c;
            }
        }

        Decimal outstanding = opp.Amount - paidTotal - writtenOffTotal;
        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // ---- Delete unpaid, not written‑off payments -----------------------
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : existingPayments) {
            if (!p.npe01__Paid__c && !p.npe01__Written_Off__c) {
                toDelete.add(p);
            }
        }
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // ---- Compute installment amounts ------------------------------------
        Decimal baseAmount = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal remainder = outstanding - (baseAmount * numberOfPayments);

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amt = baseAmount;
            if (i == numberOfPayments - 1) {
                amt = baseAmount + remainder; // last payment absorbs remainder
            }
            Date schedDate = firstPaymentDate.addMonths(i);

            npe01__OppPayment__c newPay = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amt,
                npe01__Scheduled_Date__c = schedDate,
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
                // npe01__Payment_Date__c and npe01__Payment_Method__c remain null
            );
            newPayments.add(newPay);
        }

        insert newPayments;
        return newPayments;
    }
}
