    /**
     * Inserts the given contacts in a single DML statement while suppressing the
     * TA_Contact_CreateWelcomeTask after‑insert action. The phone‑formatting
     * before‑insert action (TA_Contact_FormatPhone) continues to run.
     *
     * After the method completes the bypass is cleared so any subsequent contact
     * inserts in the same transaction will receive the welcome task as usual.
     */
    public static void importContacts(List<Contact> contacts) {
        // Bypass only the welcome‑task creation action.
