public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    public void beforeInsert(List<SObject> triggerNew) {
        process(triggerNew, null);
    }
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        process(triggerNew, triggerOld);
    }
    private void process(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> evalContacts = new List<Contact>();
        Map<Id, Contact> oldMap = (triggerOld != null) ? new Map<Id, Contact>(triggerOld) : null;
        Set<Id> accountIds = new Set<Id>();
        Set<String> lowerEmails = new Set<String>();
        Set<Id> evalContactIds = new Set<Id>();

        for (SObject s : triggerNew) {
            Contact con = (Contact)s;
            if (con.AccountId == null || con.Email == null) continue;
            Boolean check = false;
            if (triggerOld == null) {
                check = true;
            } else {
                Contact old = oldMap.get(con.Id);
                if (old == null) {
                    check = true;
                } else if (!con.Email.equals(old.Email) || !con.AccountId.equals(old.AccountId)) {
                    check = true;
                }
            }
            if (!check) continue;
            evalContacts.add(con);
            accountIds.add(con.AccountId);
            lowerEmails.add(con.Email.toLowerCase());
            if (con.Id != null) evalContactIds.add(con.Id);
        }

        if (evalContacts.isEmpty()) return;

        List<Contact> existing = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ];

        Set<String> existingKeys = new Set<String>();
        for (Contact ex : existing) {
            if (evalContactIds.contains(ex.Id)) continue;
            String key = ex.AccountId + '_' + ex.Email.toLowerCase();
            existingKeys.add(key);
        }

        Map<String, Boolean> keySeen = new Map<String, Boolean>();
        for (String k : existingKeys) {
            keySeen.put(k, true);
        }

        for (Contact con : evalContacts) {
            String key = con.AccountId + '_' + con.Email.toLowerCase();
            if (keySeen.containsKey(key)) {
                con.addError('Another contact on this account already uses this email address.');
            } else {
                keySeen.put(key, true);
            }
        }
    }
}
