public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject sobj : triggerNew) {
            Lead lead = (Lead)sobj;

            // Email: trim and lower case (null stays null)
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: set to 'Web' when blank; keep existing value otherwise (trimmed)
            if (lead.LeadSource == null || lead.LeadSource.trim() == '') {
                lead.LeadSource = 'Web';
            } else {
                lead.LeadSource = lead.LeadSource.trim();
            }
        }
    }
}
