public class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert,
                                              TriggerAction.AfterUpdate,
                                              TriggerAction.AfterDelete,
                                              TriggerAction.AfterUndelete {

    // After Insert
    public void afterInsert(List<SObject> triggerNew) {
        handleInsert((List<Case>)triggerNew);
    }

    // After Update
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        handleUpdate((List<Case>)triggerNew, (List<Case>)triggerOld);
    }

    // After Delete
    public void afterDelete(List<SObject> triggerOld) {
        handleDelete((List<Case>)triggerOld);
    }

    // After Undelete
    public void afterUndelete(List<SObject> triggerNew) {
        handleUndelete((List<Case>)triggerNew);
    }

    // ------------------- Helper methods -------------------

    private void handleInsert(List<Case> newCases) {
        Map<Id, Integer> delta = new Map<Id, Integer>();
        for (Case c : newCases) {
            if (c.AccountId == null) continue;
            if (!c.IsClosed) {
                addDelta(delta, c.AccountId, 1);
            }
        }
        applyDelta(delta);
    }

    private void handleUpdate(List<Case> newCases, List<Case> oldCases) {
        Map<Id, Case> oldMap = new Map<Id, Case>();
        for (Case c : oldCases) oldMap.put(c.Id, c);

        Map<Id, Integer> delta = new Map<Id, Integer>();
        for (Case c : newCases) {
            Case old = oldMap.get(c.Id);
            if (old == null) continue;

            Id oldAcc = old.AccountId;
            Id newAcc = c.AccountId;
            Boolean oldOpen = !old.IsClosed;
            Boolean newOpen = !c.IsClosed;

            // Account changed
            if (oldAcc != newAcc) {
                if (oldAcc != null && oldOpen) {
                    addDelta(delta, oldAcc, -1);
                }
                if (newAcc != null && newOpen) {
                    addDelta(delta, newAcc, 1);
                }
            } else {
                // Same account, check IsClosed change
                if (!oldOpen && newOpen) {
                    // closed -> open
                    addDelta(delta, c.AccountId, 1);
                } else if (oldOpen && !newOpen) {
                    // open -> closed
                    addDelta(delta, c.AccountId, -1);
                }
                // else no change
            }
        }
        applyDelta(delta);
    }

    private void handleDelete(List<Case> deletedCases) {
        Map<Id, Integer> delta = new Map<Id, Integer>();
        for (Case c : deletedCases) {
            if (c.AccountId == null) continue;
            if (!c.IsClosed) {
                addDelta(delta, c.AccountId, -1);
            }
        }
        applyDelta(delta);
    }

    private void handleUndelete(List<Case> restoredCases) {
        Map<Id, Integer> delta = new Map<Id, Integer>();
        for (Case c : restoredCases) {
            if (c.AccountId == null) continue;
            if (!c.IsClosed) {
                addDelta(delta, c.AccountId, 1);
            }
        }
        applyDelta(delta);
    }

    private void addDelta(Map<Id, Integer> delta, Id accId, Integer change) {
        if (accId == null) return;
        Integer current = delta.get(accId);
        delta.put(accId, (current == null ? 0 : current) + change);
    }

    private void applyDelta(Map<Id, Integer> delta) {
        if (delta.isEmpty()) return;

        // Query accounts to get current count
        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :delta.keySet()
        ];

        List<Account> toUpdate = new List<Account>();
        for (Account a : accounts) {
            Integer cur = a.FB_Open_Case_Count__c == null ? 0 : a.FB_Open_Case_Count__c;
            Integer change = delta.get(a.Id);
            Integer newVal = cur + change;
            if (newVal < 0) newVal = 0;
            a.FB_Open_Case_Count__c = newVal;
            toUpdate.add(a);
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
