public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        TA_Contact_Queries queries = TA_Contact_Queries.getInstance();
        Map<Id, Account> accountsById = queries.accountsById;

        for (SObject sobj : triggerNew) {
            if (!(sobj instanceof Contact)) continue;
            Contact c = (Contact)sobj;
            if (c.AccountId == null) continue;

            Account acc = accountsById.get(c.AccountId);
            if (acc == null) continue;

            boolean allMailingBlank = 
                (c.MailingStreet == null || c.MailingStreet.trim() == '') &&
                (c.MailingCity == null || c.MailingCity.trim() == '') &&
                (c.MailingPostalCode == null || c.MailingPostalCode.trim() == '') &&
                (c.MailingCountry == null || c.MailingCountry.trim() == '');

            if (allMailingBlank) {
                c.MailingStreet = acc.BillingStreet;
                c.MailingCity = acc.BillingCity;
                c.MailingPostalCode = acc.BillingPostalCode;
                c.MailingCountry = acc.BillingCountry;
            }
        }
    }
}
